// Handle file upload from webhook
const binaryData = items[0].binary?.data;
if (!binaryData) {
  throw new Error('No image data found');
}

return items.map(item => ({
  json: {
    imageData: item.binary.data,
    mimeType: item.binary.data.mimeType || 'image/jpeg',
    fileName: item.binary.data.fileName || 'business-card.jpg'
  },
  binary: item.binary
}));

// Convert image to base64 for Gemini
const binaryData = items[0].binary?.data;

if (!binaryData || !binaryData.data) {
  throw new Error('No binary image data available');
}

// Get base64 data (remove data URL prefix if present)
let base64Data = binaryData.data;
if (base64Data.includes('base64,')) {
  base64Data = base64Data.split('base64,')[1];
}

const mimeType = binaryData.mimeType || 'image/jpeg';

return [{
  json: {
    base64Image: base64Data,
    mimeType: mimeType
  }
}];

// Parse Gemini response and extract business card data
const response = items[0].json;

let extracted = {
  name: null,
  company: null,
  title: null,
  email: null,
  phone: null,
  website: null,
  address: null,
  notes: null,
  confidence: 0,
  raw_response: JSON.stringify(response)
};

try {
  // Gemini 2.5 Flash returns data in candidates[0].content.parts[0].text
  let contentText = '';

  if (response.candidates && response.candidates[0]) {
    const content = response.candidates[0].content;
    if (content && content.parts && content.parts[0]) {
      contentText = content.parts[0].text;
    }
  }

  // Try to parse JSON from content
  let parsedData = {};

  // Clean potential markdown formatting
  contentText = contentText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  if (contentText) {
    parsedData = JSON.parse(contentText);
  }

  // Map fields
  extracted = {
    name: parsedData.name || null,
    company: parsedData.company || null,
    title: parsedData.title || null,
    email: parsedData.email || null,
    phone: parsedData.phone || null,
    website: parsedData.website || null,
    address: parsedData.address || null,
    notes: parsedData.notes || '',
    confidence: parsedData.confidence || 0.8,
    timestamp: new Date().toISOString()
  };

} catch (error) {
  extracted.notes = `Parse error: ${error.message}. Raw: ${JSON.stringify(response).substring(0, 200)}`;
  extracted.confidence = 0.3;
}

return [{ json: { extracted } }];

// Plausibility checks for extracted data
const data = items[0].json.extracted;
const issues = [];

// Email validation
if (data.email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(data.email)) {
    issues.push('Invalid email format');
    data.email_valid = false;
  } else {
    data.email_valid = true;
  }
} else {
  issues.push('No email found');
  data.email_valid = false;
}

// Name validation (at least 2 parts)
if (data.name) {
  const nameParts = data.name.trim().split(/\s+/);
  if (nameParts.length < 2) {
    issues.push('Name might be incomplete');
    data.name_valid = false;
  } else {
    data.name_valid = true;
  }
} else {
  issues.push('No name found');
  data.name_valid = false;
}

// Phone validation (basic)
if (data.phone) {
  const phoneRegex = /[0-9+\-\(\)\s]{7,}/;
  data.phone_valid = phoneRegex.test(data.phone);
  if (!data.phone_valid) issues.push('Phone format suspicious');
} else {
  data.phone_valid = false;
}

// Website validation
if (data.website) {
  try {
    new URL(data.website);
    data.website_valid = true;
  } catch {
    // Try adding https://
    if (!data.website.startsWith('http')) {
      data.website = 'https://' + data.website;
    }
    data.website_valid = true;
  }
} else {
  data.website_valid = false;
}

// Overall plausibility
data.plausible = issues.length <= 1;
data.issues = issues;

return [{ json: { validated: data } }];

// Dedupe logic: check if contact exists by email or name+company
const validated = items[0].json.validated;
const existingRows = items.slice(1).map(i => i.json);

function normalize(s) {
  return (s || '').toLowerCase().replace(/[^a-z0-9]/g, '').trim();
}

const email = validated.email;
const name = normalize(validated.name);
const company = normalize(validated.company);

let foundRow = null;
let rowIndex = -1;

// Search for duplicate
for (let i = 0; i < existingRows.length; i++) {
  const row = existingRows[i];
  const rowEmail = row.email;
  const rowName = normalize(row.name);
  const rowCompany = normalize(row.company);

  // Match by email (primary)
  if (email && rowEmail && email.toLowerCase() === rowEmail.toLowerCase()) {
    foundRow = row;
    rowIndex = i + 2; // +2 because sheets are 1-indexed and have header
    break;
  }

  // Match by name + company (secondary)
  if (name && company && rowName && rowCompany) {
    if (name === rowName && company === rowCompany) {
      foundRow = row;
      rowIndex = i + 2;
      break;
    }
  }
}

if (foundRow) {
  // UPDATE existing
  const merged = {};
  for (const key of ['name', 'company', 'title', 'email', 'phone', 'website', 'address', 'notes']) {
    // Keep existing non-empty values, otherwise use new
    merged[key] = (foundRow[key] && foundRow[key] !== '') ? foundRow[key] : (validated[key] || '');
  }
  merged.last_updated = new Date().toISOString();
  merged.row_number = rowIndex;

  return [{
    json: {
      action: 'update',
      data: merged,
      rowIndex: rowIndex
    }
  }];
} else {
  // CREATE new
  const newRow = {
    name: validated.name || '',
    company: validated.company || '',
    title: validated.title || '',
    email: validated.email || '',
    phone: validated.phone || '',
    website: validated.website || '',
    address: validated.address || '',
    notes: validated.notes || '',
    created_at: new Date().toISOString(),
    last_updated: new Date().toISOString()
  };

  return [{
    json: {
      action: 'create',
      data: newRow
    }
  }];
}

// Build final response for frontend
const result = items[0].json;
const action = items[1]?.json?.action || 'unknown';

const response = {
  success: true,
  action: action, // 'update' or 'create'
  data: result.data || result,
  message: action === 'update' ? 'Contact updated successfully' : 'New contact created',
  timestamp: new Date().toISOString()
};

return [{ json: response }];
